-- Older clients use show_in_list for the long-form grid. Short articles have
-- their own listing flag, while status and display_order retain their meaning.
alter table public.feature_articles
  add column if not exists series_id text not null default 'editorial',
  add column if not exists life_stage text,
  add column if not exists show_in_series boolean not null default true;

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.feature_articles'::regclass and conname = 'feature_articles_series_check'
  ) then
    alter table public.feature_articles add constraint feature_articles_series_check check (
      (series_id = 'editorial' and life_stage is null)
      or (
        series_id = 'generational-concerns'
        and life_stage is not null
        and life_stage in ('student', 'young-adult', 'early-career', 'crossroads', 'family-formation', 'midlife-and-later')
        and not show_in_list and not is_featured
      )
    );
  end if;
end;
$$;

CREATE OR REPLACE FUNCTION public.publish_feature_article(target_id text, expected_revision integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare current_row public.feature_articles; draft_row public.feature_article_drafts; p jsonb; technique_ids text[]; theory_ids text[]; new_slug text; new_category text; new_series text; new_life_stage text;
begin
 if auth.uid() is null or not public.is_owner() then raise exception 'owner_required' using errcode='42501'; end if;
 select * into current_row from public.feature_articles where id=target_id for update;
 if not found then raise exception '記事が見つかりません。' using errcode='22023'; end if;
 select * into draft_row from public.feature_article_drafts where article_id=target_id for update;
 if not found or draft_row.revision is distinct from expected_revision or draft_row.base_updated_at is distinct from current_row.updated_at then raise exception '記事または下書きが変更されています。再読み込みしてください。' using errcode='40001'; end if;
 p:=public.feature_editorial_payload(draft_row.payload,current_row); new_slug:=coalesce(nullif(btrim(p->>'slug'),''),current_row.slug);
 new_category:=case when p ? 'category_id' then p->>'category_id' else current_row.category_id end;
 new_series:=case when p ? 'series_id' then p->>'series_id' else current_row.series_id end;
 new_life_stage:=case when p ? 'life_stage' then p->>'life_stage' else current_row.life_stage end;
 if new_series is null or new_series not in ('editorial','generational-concerns') then raise exception '記事シリーズを確認してください。' using errcode='22023'; end if;
 if new_series='generational-concerns' and (new_life_stage is null or new_life_stage not in ('student','young-adult','early-career','crossroads','family-formation','midlife-and-later')) then raise exception '人生段階を選択してください。' using errcode='22023'; end if;
 if new_category is not null and new_category not in ('relationships','self-growth','life-choices','society-era') then raise exception '主カテゴリを確認してください。' using errcode='22023'; end if;
 if new_slug !~ '^[a-z0-9][a-z0-9-]{0,79}$' then raise exception 'URL名は半角英数字とハイフンで入力してください。' using errcode='22023'; end if;
 if current_row.status<>'draft' and new_slug<>current_row.slug then raise exception '公開済みの記事のURL名は変更できません。' using errcode='22023'; end if;
 if length(btrim(coalesce(p->>'title','')))=0 or length(btrim(coalesce(p->>'body','')))=0 then raise exception 'タイトルと本文を入力してください。' using errcode='22023'; end if;
 if new_series='editorial' and coalesce(p->>'image_path','') not in ('bundled:feature-coast','bundled:feature-forest','bundled:feature-mountain') and coalesce(p->>'image_path','') not like 'feature/%' then raise exception '記事の写真を選択してください。' using errcode='22023'; end if;
 if jsonb_typeof(p->'related_technique_ids') is distinct from 'array' or jsonb_typeof(p->'related_theory_ids') is distinct from 'array' then raise exception '関連する知識を確認してください。' using errcode='22023'; end if;
 select coalesce(array_agg(value order by first_position),'{}') into technique_ids from (select value,min(ordinality) first_position from jsonb_array_elements_text(p->'related_technique_ids') with ordinality group by value) ordered;
 select coalesce(array_agg(value order by first_position),'{}') into theory_ids from (select value,min(ordinality) first_position from jsonb_array_elements_text(p->'related_theory_ids') with ordinality group by value) ordered;
 if exists(select 1 from unnest(technique_ids) requested(id) where not exists(select 1 from public.techniques t where t.id=requested.id and t.status='published')) or exists(select 1 from unnest(theory_ids) requested(id) where not exists(select 1 from public.theories t where t.id=requested.id and t.status='published')) then raise exception '関連する知識は公開中のものを選択してください。' using errcode='22023'; end if;
 update public.feature_articles set editorial_character_id=p->>'editorial_character_id',related_feature_ids=array(select value from jsonb_array_elements_text(p->'related_feature_ids')),source_references=p->'source_references',category_id=new_category,
  series_id=new_series,life_stage=case when new_series='generational-concerns' then new_life_stage end,
  show_in_series=coalesce((p->>'show_in_series')::boolean,current_row.show_in_series),
  slug=new_slug,title=btrim(p->>'title'),lead=coalesce(p->>'lead',''),body=p->>'body',image_path=p->>'image_path',image_alt=coalesce(p->>'image_alt',''),is_featured=new_series='editorial' and coalesce((p->>'is_featured')::boolean,false),show_in_list=new_series='editorial' and coalesce((p->>'show_in_list')::boolean,true),display_order=coalesce((p->>'display_order')::integer,100),related_technique_ids=technique_ids,related_theory_ids=theory_ids,status='published',updated_at=clock_timestamp() where id=target_id;
 delete from public.feature_article_drafts where article_id=target_id;
end $function$
;

-- Titles, subtitles and Markdown bodies from jinsei_no_nayami_all_21.md.
-- On replay, retain any CMS edits and fail if a slug is owned by another article.
do $seed$
declare
  articles jsonb := $articles$[
  {
    "slug": "life-group-exclusion",
    "title": "集団から外れることへの恐怖",
    "lead": "一人になることが、なぜあんなに怖かったのか",
    "body": "昼休み、いつものグループが自分を待たずに移動している。たったそれだけで、胸がざわつくことがあります。悪口を言われたわけでも、仲間外れにされたと決まったわけでもない。それでも「自分の居場所がなくなるかもしれない」と考えてしまうのです。\n\n学生時代の集団には、大人の人間関係とは違う切実さがあります。教室という限られた場所で毎日顔を合わせ、誰と一緒に過ごしているかが周囲からも見えるからです。\n\n## なぜ、集団はこれほど大きく見えるのか\n\n学校では、同じ顔ぶれと長い時間を過ごします。関係がこじれても、翌日から簡単に別の場所へ移れるとは限りません。友達グループは楽しさを与える一方で、そこから外れることが目に見える仕組みにもなっています。\n\nそのため、本当は乗り気でない遊びに参加したり、笑えない冗談に合わせたりすることがあります。集団に所属する安心感と、自分の気持ちを抑える負担が、同時に生まれるのです。\n\nここで忘れたくないのは、集団から外れることへの恐怖は、必ずしも弱さを意味しないということです。人とのつながりを必要とするのは自然なことですし、とりわけ逃げ場の限られた学校では、その重みが増します。\n\n## 居場所は一つでなくていい\n\nただ、教室のグループが人間関係のすべてではありません。部活動、習い事、趣味の仲間、学校の外の人たち。所属する場所が増えるほど、一つの集団での出来事が、自分の価値を決める力は弱まっていきます。\n\n友達に合わせることが必要な場面もあります。しかし、**一緒にいられることと、自分を消してまで居続けることは違います。**\n\n集団の外に出る怖さをすぐに消すことはできなくても、「ここで受け入れられなければ終わり」という思い込みは、少しずつ変えていけるのだと思います。",
    "life_stage": "student",
    "display_order": 10
  },
  {
    "slug": "life-school-hierarchy",
    "title": "スクールカーストの息苦しさ",
    "lead": "教室の序列は、誰が決めているのか",
    "body": "教室に入ると、誰が中心にいて、誰が目立たず、誰の発言なら笑いが起こるのかが、何となくわかる。明文化されたルールはないのに、そこには見えない序列が存在することがあります。\n\nこうした関係を「スクールカースト」と呼ぶことがあります。しかし、教室での立場は、学力や性格だけで決まるものではありません。声の大きさ、運動部での活躍、流行への感度、たまたま仲良くなった友人など、さまざまな条件が重なっています。\n\n## 教室だけで通用する物差し\n\n学校は人間関係の相手を自由に選びにくい場所です。限られた集団の中で評判が広がり、「明るい人」「いじられる人」「おとなしい人」といった役割が定着することがあります。\n\n一度ついた役割を変えようとしても、「キャラじゃない」と言われる。周囲の期待が、本人の振る舞いまで縛ってしまうのです。\n\nしかし、ある教室で人気があることと、社会のあらゆる場面で評価されることは同じではありません。学校であまり目立たなかった人が、大学や職場で頼られるようになることもあります。反対に、学校での人気がそのまま続くとは限りません。\n\n## 序列を人生の成績にしない\n\n教室の序列が苦しいのは、その場所の評価が世界全体の評価のように感じられるからでしょう。毎日同じ空間にいると、そこにしか物差しがないように思えてきます。\n\nもちろん、実際のいじめや排除が起きているなら、単なる気の持ちようで済ませるべきではありません。学校の外の大人や相談先に助けを求めることが必要です。\n\nそのうえで覚えておきたいのは、**教室での立ち位置は、その人の人生に付けられた順位ではない**ということです。\n\n環境が変われば、評価される性質も、自然に取れる役割も変わります。今いる集団の中の自分が、自分のすべてとは限らないのです。",
    "life_stage": "student",
    "display_order": 20
  },
  {
    "slug": "life-missing-out-on-youth",
    "title": "青春を楽しめなかった後悔",
    "lead": "思い描いた学生生活を送れなかった人へ",
    "body": "卒業式の日、周囲が泣きながら写真を撮っている。SNSには、部活動や文化祭、恋愛を楽しんだ人たちの思い出が並ぶ。一方で、自分には「これが青春だった」と胸を張れる記憶があまりない。そんな寂しさを抱くことがあります。\n\n青春は、人生の中でも特別な時間として描かれがちです。だからこそ、その時期を十分に楽しめなかった人は、何か大切なものを取り逃したように感じるのでしょう。\n\n## 「理想の青春」はどこから来たのか\n\n映画や漫画、SNSで目にする青春には、わかりやすい場面があります。仲の良いグループ、熱中した部活動、文化祭の成功、甘酸っぱい恋愛。こうした経験は確かに魅力的です。\n\nしかし、誰もがそのような学生生活を送れるわけではありません。友人関係に悩んだ人も、勉強や家庭の事情に追われた人も、一人で過ごす時間が多かった人もいるでしょう。\n\nしかも、他人が公開するのは楽しかった場面が中心です。そこに至るまでの退屈な日々や孤独、衝突は見えにくい。自分の生活の全体と、他人の思い出の名場面を比べれば、見劣りしてしまうのも無理はありません。\n\n## 取り戻せない時間と、これからの経験\n\n学生時代にしかできないことは確かにあります。制服で通学する日々や、同じ教室で毎日会える関係を、そのままやり直すことはできません。その喪失を無理に否定する必要はないでしょう。\n\nただ、友達と夢中で遊ぶこと、新しいことに挑戦すること、誰かを好きになることまで、卒業と同時に終わるわけではありません。\n\n**「あの頃しかできなかったこと」と「これからもできること」を分けて考える。**\n\n青春への後悔は、過去を変えられない苦しさであると同時に、これからどんな時間を持ちたいのかを教えてくれる感情でもあるのだと思います。",
    "life_stage": "student",
    "display_order": 30
  },
  {
    "slug": "life-friendship-after-graduation",
    "title": "卒業とともに失われる友情",
    "lead": "毎日一緒にいた人が、なぜ遠くなるのか",
    "body": "卒業の日には「また絶対に集まろう」と言っていたのに、数か月後には連絡が減り、いつの間にか近況もわからなくなる。あれほど身近だった友人が、少しずつ遠い存在になっていくことがあります。\n\n喧嘩をしたわけでも、嫌いになったわけでもありません。それなのに関係が薄れていくのは、友情の中に、私たちが思う以上に生活の仕組みが関わっていたからかもしれません。\n\n## 毎日会えることの大きさ\n\n学校では、約束をしなくても友達に会えます。同じ授業を受け、休み時間に話し、帰り道をともにする。その日の出来事を共有するから、翌日にも新しい話題が生まれます。\n\n卒業すると、こうした日常の接点が一度に失われます。会うためには予定を合わせる必要があり、近況を知るには自分から連絡しなければなりません。友情の維持が、自然に起きるものから、互いの意思と時間を必要とするものに変わるのです。\n\n進学先や職場が違えば、新しい出会いも増えます。生活の中心が変わるにつれ、連絡の間隔が長くなることもあるでしょう。\n\n## 疎遠になったら、友情は終わりなのか\n\n連絡が減ったことを、相手にとって自分が大切でなくなった証拠と考えたくなることがあります。しかし、返事の頻度だけで、かつての関係の価値を測ることはできません。\n\n何年ぶりに会って再び親しくなる友人もいれば、思い出の中で大切な存在になっていく友人もいます。\n\n**友情には、同じ日常を生きる時期があっても、同じ日常を生き続ける義務はありません。**\n\n卒業によって失うのは、友達そのものというより、毎日会えた生活かもしれません。だからこそ、当時の親しさまで嘘だったと思わなくてよいのだと思います。",
    "life_stage": "student",
    "display_order": 40
  },
  {
    "slug": "life-wanting-to-be-someone",
    "title": "何者かになりたい病",
    "lead": "肩書きのない自分では、物足りない",
    "body": "同世代が起業した、人気者になった、大きな賞を取った。そんなニュースに触れると、自分の日常が急に平凡に見えてしまうことがあります。\n\n特別な才能があるわけでも、明確な夢があるわけでもない。それでも「このまま普通の人として終わりたくない」と思う。青年期には、そんな焦りが生まれることがあります。\n\n## 「何者か」とは誰なのか\n\nこの願望の厄介なところは、目指すものが曖昧なことです。仕事で成果を出したいのか、誰かに認められたいのか、充実した日々を送りたいのか。区別しないまま「すごい人になりたい」と考えると、何を達成しても満たされにくくなります。\n\nSNSでは、若くして成功した人が目立ちます。華やかな肩書きや数字は、他人から見てもわかりやすい指標です。そのため、何者かになることが、自分の人生を肯定する条件のように思えてくるのです。\n\nしかし、周囲に評価される肩書きと、本人が納得して送る人生は、必ずしも一致しません。\n\n## 肩書きの前にある生活\n\n何かを成し遂げたい気持ちは、挑戦する力にもなります。大切なのは、その願望が、自分の関心から生まれているのか、他人に見せたい姿から生まれているのかを見分けることです。\n\nたとえば「起業家になりたい」と思ったとき、事業を育てる仕事に惹かれているのか、起業家と呼ばれる自分に惹かれているのか。両方あるとしても、その比重によって次の行動は変わります。\n\n**何者かになることを急ぐあまり、何をしたいのかを見失っては本末転倒です。**\n\n人間の価値は肩書きが付いて初めて生まれるものではありません。何を面白がり、誰と過ごし、どんなことを積み重ねたいのか。その輪郭が少しずつ見えてくることも、青年期の大切な前進なのでしょう。",
    "life_stage": "young-adult",
    "display_order": 10
  },
  {
    "slug": "life-feeling-behind",
    "title": "人生に出遅れたという焦り",
    "lead": "同い年なのに、どうしてこんなに差があるのか",
    "body": "同級生が内定を得た。友人が恋人と同棲を始めた。知り合いが海外へ飛び立った。そんな知らせを聞くたびに、自分だけが立ち止まっている気がすることがあります。\n\n人生に「何歳までに何をする」という公式の進度表はありません。それでも私たちは、同世代の近況を見ながら、見えない順位を付けてしまいます。\n\n## 比較する相手が増えすぎた時代\n\n学校では、学年や試験によって進度が可視化されます。社会に出ても、その感覚が残ることがあります。就職、収入、結婚、経験の数。違う種類の出来事まで、一つの「進んでいる・遅れている」にまとめてしまうのです。\n\nさらにSNSでは、ある人の仕事の成功、別の人の恋愛、また別の人の旅行を同時に目にします。誰か一人と比べているつもりでも、実際には大勢の人の一番華やかな部分をつなぎ合わせた理想像と競争しているのかもしれません。\n\nもちろん、資格や進路など、時期が影響する選択はあります。しかし、人生全体を一本のレースのように捉えると、何をしていても誰かに負けている気分になります。\n\n## 自分にとっての「遅れ」を考える\n\n焦りを感じたときは、何に遅れているのかを具体的にしてみることが役立ちます。希望する仕事に必要な準備が足りないのか。それとも、周囲が先に進んで見えるだけなのか。\n\n前者なら行動を考えられますが、後者には明確なゴールがありません。\n\n**他人の人生で起きた出来事は、自分の人生の締め切りではありません。**\n\n同じ年齢でも、育った環境も、望むものも、選べる条件も違います。出遅れたように見える時間が、別の経験を積む時間になっていることもあるのです。",
    "life_stage": "young-adult",
    "display_order": 20
  },
  {
    "slug": "life-fear-of-losing-youth",
    "title": "若さを失う予期不安",
    "lead": "まだ若いのに、若くなくなる日が怖い",
    "body": "二十歳になったばかりなのに、もう二十代の終わりが気になる。「学生のうちに」「若いうちに」という言葉を聞くたび、今の時間が減っていくように感じることがあります。\n\n本来なら楽しめるはずの現在を、まだ訪れていない未来への不安が覆ってしまう。これが、若さを失うことへの予期不安の厄介なところです。\n\n## 若さに集められた多くの価値\n\n社会では、若さが可能性や自由、魅力と結びつけられがちです。青春映画やSNSでも、若い時期の恋愛、友人関係、旅行が特別に輝いて描かれます。\n\nそのため、若さを「いつか失う貴重な資格」のように考えてしまうことがあります。すると、休日を家で過ごしただけで損をした気分になる。恋愛経験が少なければ、取り戻せない時間を失ったように感じるのです。\n\nもちろん、年齢によって変わることはあります。体力や生活上の責任、参加しやすい環境には違いが生まれます。だからこそ、この不安を単なる思い込みだと片づけることもできません。\n\nただし、若さにできることのすべてが、若い間にしかできないわけではありません。\n\n## 未来の喪失で現在を削らない\n\n「今しかない」と考えることは、行動するきっかけにもなります。一方で、その気持ちが強すぎると、経験の一つひとつを充実度で採点し始めます。\n\n旅行中も「もっと楽しむべきだ」と考え、休んでいても「時間を無駄にした」と焦る。それでは、若さを大切にしようとするほど、今を楽しめなくなってしまいます。\n\n**若さを失うことへの不安と、若さを生きることは別の営みです。**\n\n将来の自分を想像するのは悪いことではありません。ただ、まだ来ていない喪失を先取りして、現在の喜びまで手放す必要はないのでしょう。",
    "life_stage": "young-adult",
    "display_order": 30
  },
  {
    "slug": "life-third-year-at-work",
    "title": "社会人3年目の壁",
    "lead": "仕事に慣れた頃、なぜ迷いが始まるのか",
