]$articles$::jsonb;
begin
  if exists (
    select 1 from jsonb_to_recordset(articles) as seed(slug text)
    join public.feature_articles as existing using (slug)
    where existing.id <> seed.slug
  ) then
    raise exception 'A generational concern slug belongs to a different article.';
  end if;

  insert into public.feature_articles
    (id, slug, title, lead, body, life_stage, display_order, series_id, status, show_in_list, is_featured)
  select slug, slug, title, lead, body, life_stage, display_order, 'generational-concerns', 'published', false, false
  from jsonb_to_recordset(articles) as seed(slug text, title text, lead text, body text, life_stage text, display_order integer)
  on conflict (slug) do nothing;
end;
$seed$;
